<?php
require __DIR__.'/_auth.php';$pdo=admin_db();if(!$pdo)exit('Database unavailable.');$id=(int)($_GET['id']??0);$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'&&$id){$st=$pdo->prepare('DELETE FROM packages WHERE id=?');$st->execute([$id]);header('Location:/admin/packages.php');exit;}
$title=trim($_POST['title']??'');$slug=preg_replace('/[^a-z0-9-]+/','-',strtolower(trim($_POST['slug']??$title)));$days=max(1,(int)($_POST['duration_days']??1));$data=[$slug,$title,trim($_POST['category']??''),$days,trim($_POST['tour_type']??''),trim($_POST['location']??''),trim($_POST['summary']??''),trim($_POST['overview']??''),trim($_POST['inclusions']??''),trim($_POST['exclusions']??''),trim($_POST['important_notes']??''),trim($_POST['featured_image']??''),($_POST['status']??'draft')==='published'?'published':'draft',trim($_POST['meta_title']??''),trim($_POST['meta_description']??'')];if($id){$st=$pdo->prepare('UPDATE packages SET slug=?,title=?,category=?,duration_days=?,tour_type=?,location=?,summary=?,overview=?,inclusions=?,exclusions=?,important_notes=?,featured_image=?,status=?,meta_title=?,meta_description=?,updated_at=NOW() WHERE id=?');$st->execute([...$data,$id]);}else{$st=$pdo->prepare('INSERT INTO packages(slug,title,category,duration_days,tour_type,location,summary,overview,inclusions,exclusions,important_notes,featured_image,status,meta_title,meta_description,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())');$st->execute($data);$id=(int)$pdo->lastInsertId();}
if(isset($_POST['day_title'])){foreach($_POST['day_title'] as $n=>$dt){$n=(int)$n;$body=trim($_POST['day_body'][$n]??'');$dt=trim($dt);if(!$dt&&!$body)continue;$st=$pdo->prepare('INSERT INTO itinerary_days(package_id,day_number,title,body,accommodation,meals,altitude,drive_time) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),body=VALUES(body),accommodation=VALUES(accommodation),meals=VALUES(meals),altitude=VALUES(altitude),drive_time=VALUES(drive_time)');$st->execute([$id,$n,$dt,$body,trim($_POST['day_accommodation'][$n]??''),trim($_POST['day_meals'][$n]??''),trim($_POST['day_altitude'][$n]??''),trim($_POST['day_drive'][$n]??'')]);}}
$count=(int)$pdo->query('SELECT COUNT(*) FROM itinerary_days WHERE package_id='.(int)$id)->fetchColumn();if(($_POST['status']??'draft')==='published'&&$count!==$days){$pdo->prepare("UPDATE packages SET status='draft' WHERE id=?")->execute([$id]);$msg="Saved as draft: duration is $days days but itinerary has $count day records.";}else{$msg='Package saved.';}}
$pkg=$id?$pdo->prepare('SELECT * FROM packages WHERE id=?'):null;if($pkg){$pkg->execute([$id]);$pkg=$pkg->fetch();}$it=[];if($id){$st=$pdo->prepare('SELECT * FROM itinerary_days WHERE package_id=? ORDER BY day_number');$st->execute([$id]);foreach($st->fetchAll() as $d)$it[$d['day_number']]=$d;}$list=$pdo->query('SELECT id,title,slug,category,duration_days,status,updated_at FROM packages ORDER BY updated_at DESC')->fetchAll();$daysForm=(int)($pkg['duration_days']??7);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>Packages CMS</title></head><body><main class="section wrap"><div class="section-head"><div><span class="eyebrow dark-text">CMS</span><h1>Packages & Itineraries</h1></div><div><a class="btn light" href="/admin/">Dashboard</a> <a class="btn dark" href="/admin/packages.php">New Package</a></div></div><?php if($msg):?><p><strong><?=e($msg)?></strong></p><?php endif;?><div class="content-layout"><section><form class="contact-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="title" value="<?=e($pkg['title']??'')?>" placeholder="Package title" required><input name="slug" value="<?=e($pkg['slug']??'')?>" placeholder="slug"><div class="three"><input name="category" value="<?=e($pkg['category']??'')?>" placeholder="Category"><input type="number" min="1" name="duration_days" value="<?=e($daysForm)?>" placeholder="Days"><input name="tour_type" value="<?=e($pkg['tour_type']??'')?>" placeholder="Tour type"></div><input name="location" value="<?=e($pkg['location']??'')?>" placeholder="Location"><textarea name="summary" placeholder="Short summary"><?=e($pkg['summary']??'')?></textarea><textarea name="overview" placeholder="Tour overview"><?=e($pkg['overview']??'')?></textarea><textarea name="inclusions" placeholder="Inclusions — one per line"><?=e($pkg['inclusions']??'')?></textarea><textarea name="exclusions" placeholder="Exclusions — one per line"><?=e($pkg['exclusions']??'')?></textarea><textarea name="important_notes" placeholder="Important notes"><?=e($pkg['important_notes']??'')?></textarea><input name="featured_image" value="<?=e($pkg['featured_image']??'')?>" placeholder="Featured image path"><input name="meta_title" value="<?=e($pkg['meta_title']??'')?>" placeholder="SEO title"><textarea name="meta_description" placeholder="SEO description"><?=e($pkg['meta_description']??'')?></textarea><select name="status"><option value="draft" <?=($pkg['status']??'draft')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($pkg['status']??'')==='published'?'selected':''?>>Published</option></select><h2>Itinerary Days</h2><?php for($n=1;$n<=$daysForm;$n++):$d=$it[$n]??[];?><fieldset style="border:1px solid #ddd;padding:16px;margin-bottom:16px"><legend>Day <?=$n?></legend><input name="day_title[<?=$n?>]" value="<?=e($d['title']??'')?>" placeholder="Day title"><textarea name="day_body[<?=$n?>]" placeholder="Detailed itinerary"><?=e($d['body']??'')?></textarea><div class="three"><input name="day_accommodation[<?=$n?>]" value="<?=e($d['accommodation']??'')?>" placeholder="Accommodation (verified only)"><input name="day_meals[<?=$n?>]" value="<?=e($d['meals']??'')?>" placeholder="Meals"><input name="day_altitude[<?=$n?>]" value="<?=e($d['altitude']??'')?>" placeholder="Altitude"></div><input name="day_drive[<?=$n?>]" value="<?=e($d['drive_time']??'')?>" placeholder="Drive / trek time"></fieldset><?php endfor;?><button class="btn gold">Save Package</button><?php if($id):?><button class="btn" name="action" value="delete" onclick="return confirm('Delete this package?')">Delete</button><?php endif;?></form></section><aside><h2>Existing Packages</h2><?php foreach($list as $r):?><p><a href="/admin/packages.php?id=<?=$r['id']?>"><strong><?=e($r['title'])?></strong></a><br><small><?=e($r['duration_days'])?> days · <?=e($r['category'])?> · <?=e($r['status'])?></small></p><?php endforeach;?></aside></div></main></body></html>
